fieldsInfo.css:
.pcraft-gantt-table { width: 100%; border-collapse: collapse; font-size: 11px; }
.pcraft-gantt-table th, .pcraft-gantt-table td { border: 1px solid #999; padding: 3px 6px; vertical-align: middle; }
.pcraft-gantt-head { background: #2c3e50; color: #fff; }
.pcraft-gantt-row:nth-child(even) { background: #f6f8fa; }
.pcraft-gantt-bar { position: relative; display: inline-block; width: 120px; height: 10px; background: #e5e7eb; vertical-align: middle; margin-right: 6px; }
.pcraft-gantt-fill { height: 10px; background: #3498db; }
.pcraft-gantt-table .value-right { text-align: right; }
.table-header { font-size: 16px; font-weight: bold; margin: 0 0 8px; }
.table-header-title small { font-size: 11px; font-weight: normal; color: #444; margin-left: 12px; }
.table-header-page { font-size: 12px; font-weight: normal; color: #666; margin-left: 12px; }
.pcraft-gantt-info { border-collapse: collapse; font-size: 11px; margin: 0 0 8px; width: 100%; }
.pcraft-gantt-info th { width: 110px; text-align: left; background: #eef2f6; border: 1px solid #c9ced3; padding: 3px 6px; font-weight: normal; color: #333; }
.pcraft-gantt-info td { border: 1px solid #c9ced3; padding: 3px 6px; }
